import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"CLI command reference","description":"","frontmatter":{"title":"CLI command reference","docId":"developer.cli","translationKey":"developer.cli","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","translationRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","order":75},"headers":[],"relativePath":"en/developer/cli.md","filePath":"en/developer/cli.md","lastUpdated":1795727787000}`),a={name:`en/developer/cli.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cli-command-reference" tabindex="-1">CLI command reference <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to “CLI command reference”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Discover every <code>tiktools</code> command form without reading Rust sources or parsing human help output. Have a matching <code>tiktools</code> binary built; the command reference is offline and never needs a running host. The canonical source is the command spec registry in <code>crates/tiktools-cli/src/commands/spec.rs</code>; each domain module owns the usage strings its parser reports in errors, so this reference cannot drift from what the parser accepts.</p><h2 id="inspect-help-offline" tabindex="-1">Inspect help offline <a class="header-anchor" href="#inspect-help-offline" aria-label="Permalink to “Inspect help offline”">​</a></h2><p>Human help groups verbs by domain; filtering renders one domain section. The <code>--json</code> form prints the machine-readable registry every agent should prefer: usage, summary and a destructive marker per verb, plus the global CLI conventions, versioned by the top-level <code>schema</code> field.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Usage errors print only the relevant form with a hint instead of the full page, so a typo never scrolls the terminal. Exit code 2 always means a usage error; see the conventions footer for host resolution, output and secret-redaction rules.</p><h2 id="generated-command-reference" tabindex="-1">Generated command reference <a class="header-anchor" href="#generated-command-reference" aria-label="Permalink to “Generated command reference”">​</a></h2><p>Generated from the checked-in CLI help snapshot in <code>docs/contracts/cli-help.json</code>; the binary remains authoritative. Usage lines are parser syntax and stay in English in every locale; summaries and conventions come from the CLI&#39;s own translation catalogs, so this reference cannot diverge from what <code>tiktools help</code> prints in the same language. Verbs marked destructive mutate or destroy state; scripts should confirm before executing them.</p><p><code>tiktools [--json] [--standalone] &lt;command&gt; [args]</code></p><h3 id="tiktools-plugin-—-install-and-manage-plugins" tabindex="-1"><code>tiktools plugin</code> — install and manage plugins <a class="header-anchor" href="#tiktools-plugin-—-install-and-manage-plugins" aria-label="Permalink to “tiktools plugin — install and manage plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>list installed plugins</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>read one plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>install from a file, id@version or url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>uninstall a plugin <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>search packages in the registry</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspect a package spec before installing</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>list installed plugins with available updates</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>update one plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>update every outdated plugin</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>roll back to a previous version <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>list available versions of a plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>pin a plugin to its current version</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>remove the version pin</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>set channel and auto-update policy</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>list package jobs</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspect one package job</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancel a running package job <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>enable a plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>disable a plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>start a plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>stop a plugin <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>read plugin settings</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>write plugin settings</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>reset plugin settings <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>plugin health check</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>options of an action type or field</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>run a plugin action</td></tr><tr><td><code>tiktools plugin commands</code></td><td>list commands contributed by installed plugins</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>describe one contributed command</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invoke a plugin-contributed command</td></tr></tbody></table><h3 id="tiktools-cloud-—-cloud-account-and-portable-backup-restore-override-with-tiktools-cloud-origin" tabindex="-1"><code>tiktools cloud</code> — cloud account and portable backup/restore (override with TIKTOOLS_CLOUD_ORIGIN) <a class="header-anchor" href="#tiktools-cloud-—-cloud-account-and-portable-backup-restore-override-with-tiktools-cloud-origin" aria-label="Permalink to “tiktools cloud — cloud account and portable backup/restore (override with TIKTOOLS_CLOUD_ORIGIN)”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>cloud account status</td></tr><tr><td><code>tiktools cloud login</code></td><td>sign in through the system browser</td></tr><tr><td><code>tiktools cloud logout</code></td><td>sign out <strong>destructive</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>restore the cloud session</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>write a portable backup archive</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>inspect a backup archive</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>restore a backup archive <strong>destructive</strong></td></tr></tbody></table><h3 id="tiktools-publisher-—-cloud-publisher-flow-requires-sign-in" tabindex="-1"><code>tiktools publisher</code> — cloud publisher flow (requires sign-in) <a class="header-anchor" href="#tiktools-publisher-—-cloud-publisher-flow-requires-sign-in" aria-label="Permalink to “tiktools publisher — cloud publisher flow (requires sign-in)”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>list publisher namespaces</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>create a publisher namespace</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>delete a namespace or publisher <strong>destructive</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>list signing keys of a publisher</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>enroll a publisher key; reads the backend password from stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>upload a plugin package</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>submit an upload for review</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>create a release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publish a release</td></tr></tbody></table><h3 id="tiktools-registry-—-package-registries-and-the-cloud-catalog" tabindex="-1"><code>tiktools registry</code> — package registries and the cloud catalog <a class="header-anchor" href="#tiktools-registry-—-package-registries-and-the-cloud-catalog" aria-label="Permalink to “tiktools registry — package registries and the cloud catalog”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>list configured registries</td></tr><tr><td><code>tiktools registry refresh</code></td><td>refresh registry metadata</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>show one registry package</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>search the cloud catalog</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>cloud catalog summaries page</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versions of one cloud catalog package</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>pagination capabilities of the cloud catalog</td></tr><tr><td><code>tiktools registry defaults</code></td><td>default registry configuration</td></tr></tbody></table><h3 id="tiktools-processor-—-event-processors" tabindex="-1"><code>tiktools processor</code> — event processors <a class="header-anchor" href="#tiktools-processor-—-event-processors" aria-label="Permalink to “tiktools processor — event processors”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>list processors</td></tr><tr><td><code>tiktools processor status</code></td><td>processor pipeline status</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>run one processor against a sample event</td></tr></tbody></table><h3 id="tiktools-live-—-tiktok-live-connection" tabindex="-1"><code>tiktools live</code> — TikTok LIVE connection <a class="header-anchor" href="#tiktools-live-—-tiktok-live-connection" aria-label="Permalink to “tiktools live — TikTok LIVE connection”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>connect to a live room</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>pick a live room interactively</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>discover live channels; works without a session</td></tr><tr><td><code>tiktools live disconnect</code></td><td>disconnect from the current room <strong>destructive</strong></td></tr><tr><td><code>tiktools live status</code></td><td>current connection status</td></tr></tbody></table><h3 id="tiktools-points-—-viewer-loyalty-points" tabindex="-1"><code>tiktools points</code> — viewer loyalty points <a class="header-anchor" href="#tiktools-points-—-viewer-loyalty-points" aria-label="Permalink to “tiktools points — viewer loyalty points”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>read the points configuration</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>update the points configuration</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>read one viewer&#39;s balance</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>add or subtract points for a viewer</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>top viewers by balance</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>reset one viewer or every balance <strong>destructive</strong></td></tr></tbody></table><h3 id="tiktools-ranking-—-viewer-ranking-definitions-and-state" tabindex="-1"><code>tiktools ranking</code> — viewer ranking definitions and state <a class="header-anchor" href="#tiktools-ranking-—-viewer-ranking-definitions-and-state" aria-label="Permalink to “tiktools ranking — viewer ranking definitions and state”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>list ranking definitions</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>metrics available to ranking definitions</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>create a ranking definition</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>update a ranking definition</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>read one ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>current standings of one ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>delete a ranking <strong>destructive</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>reset accumulated state <strong>destructive</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pause accumulation</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>resume accumulation</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>add an external contribution</td></tr></tbody></table><h3 id="tiktools-competition-—-timed-viewer-competitions" tabindex="-1"><code>tiktools competition</code> — timed viewer competitions <a class="header-anchor" href="#tiktools-competition-—-timed-viewer-competitions" aria-label="Permalink to “tiktools competition — timed viewer competitions”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>list competitions</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>read one competition</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>create a competition</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>update a competition</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>delete a competition <strong>destructive</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>current competition state</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>final or intermediate results</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>record a competition action</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>flag an action as uncertain</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolve an uncertain action</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>start a competition</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finish a competition <strong>destructive</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>winner candidates</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>select the winner</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pause a competition</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>resume a competition</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancel a competition <strong>destructive</strong></td></tr></tbody></table><h3 id="tiktools-automation-—-event-and-action-automation-rules" tabindex="-1"><code>tiktools automation</code> — event and action automation rules <a class="header-anchor" href="#tiktools-automation-—-event-and-action-automation-rules" aria-label="Permalink to “tiktools automation — event and action automation rules”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>list automation rules</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>template context available to rules</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>read one rule</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>create a rule</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>update a rule</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>delete a rule <strong>destructive</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>enable a rule</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>disable a rule</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>dry-run a rule against a sample event</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>fire a trigger manually</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>apply a moderation penalty in points</td></tr></tbody></table><h3 id="tiktools-globals-—-shared-key-value-globals-across-plugins" tabindex="-1"><code>tiktools globals</code> — shared key/value globals across plugins <a class="header-anchor" href="#tiktools-globals-—-shared-key-value-globals-across-plugins" aria-label="Permalink to “tiktools globals — shared key/value globals across plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>list every global key</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>read one global</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>write one global</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>delete one global <strong>destructive</strong></td></tr></tbody></table><h3 id="tiktools-workflow-—-visual-workflow-graphs" tabindex="-1"><code>tiktools workflow</code> — visual workflow graphs <a class="header-anchor" href="#tiktools-workflow-—-visual-workflow-graphs" aria-label="Permalink to “tiktools workflow — visual workflow graphs”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>list saved workflow graphs</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>read one graph</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>create or replace a graph</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>delete a graph <strong>destructive</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>enable a graph</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>disable a graph</td></tr></tbody></table><h3 id="tiktools-media-—-media-file-validation-and-playback" tabindex="-1"><code>tiktools media</code> — media file validation and playback <a class="header-anchor" href="#tiktools-media-—-media-file-validation-and-playback" aria-label="Permalink to “tiktools media — media file validation and playback”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>validate a media file before use in actions</td></tr></tbody></table><h3 id="tiktools-system-—-host-information-and-diagnostics" tabindex="-1"><code>tiktools system</code> — host information and diagnostics <a class="header-anchor" href="#tiktools-system-—-host-information-and-diagnostics" aria-label="Permalink to “tiktools system — host information and diagnostics”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>host version and runtime information</td></tr><tr><td><code>tiktools system health</code></td><td>component health report</td></tr><tr><td><code>tiktools system snapshot</code></td><td>full state snapshot for debugging</td></tr><tr><td><code>tiktools system doctor</code></td><td>diagnose common setup problems</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>ask the desktop user for input access</td></tr><tr><td><code>tiktools system shutdown</code></td><td>shut down the running host <strong>destructive</strong></td></tr></tbody></table><h3 id="tiktools-template-—-reusable-automation-templates-and-profiles" tabindex="-1"><code>tiktools template</code> — reusable automation templates and profiles <a class="header-anchor" href="#tiktools-template-—-reusable-automation-templates-and-profiles" aria-label="Permalink to “tiktools template — reusable automation templates and profiles”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>import a template as automation rules</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>export an event rule as a template</td></tr><tr><td><code>tiktools template list</code></td><td>list templates in the gallery</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>delete a template <strong>destructive</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>import a whole automation profile</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>export the automation profile</td></tr></tbody></table><h3 id="tiktools-api-—-generic-agent-oriented-control-surface-over-host-methods" tabindex="-1"><code>tiktools api</code> — generic agent-oriented control surface over host methods <a class="header-anchor" href="#tiktools-api-—-generic-agent-oriented-control-surface-over-host-methods" aria-label="Permalink to “tiktools api — generic agent-oriented control surface over host methods”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools api discover [--format json&amp;#124;human]</code></td><td>list every method live from the host registry</td></tr><tr><td><code>tiktools api schema &lt;method&gt; [--format json&amp;#124;human]</code></td><td>one method&#39;s description, flags and schemas</td></tr><tr><td><code>tiktools api call &lt;method&gt; [params-json] [--timeout SEC] [--dry-run] [--confirm] [--redact&amp;#124;--secrets-visible] [--explain] [--format json&amp;#124;human] [--expected-revision N] [--command-id ID --host-instance-id ID] [--include-meta]</code></td><td>validate and execute one method; destructive methods need --confirm</td></tr><tr><td><code>tiktools api events [--topics t,...] [--timeout SEC] [--max-events N]</code></td><td>stream NDJSON domain events</td></tr><tr><td><code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code></td><td>search the bounded feed journal</td></tr><tr><td><code>tiktools api verify [--coverage&amp;#124;--smoke] [--sandbox] [--timeout SEC]</code></td><td>verify the control surface against the host</td></tr></tbody></table><h3 id="tiktools-host-—-headless-host-runtimes-and-the-raw-rpc-passthrough" tabindex="-1"><code>tiktools host</code> — headless host runtimes and the raw rpc passthrough <a class="header-anchor" href="#tiktools-host-—-headless-host-runtimes-and-the-raw-rpc-passthrough" aria-label="Permalink to “tiktools host — headless host runtimes and the raw rpc passthrough”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools host --stdio [--events]</code></td><td>headless host on stdio; streams events with --events</td></tr><tr><td><code>tiktools host --ipc</code></td><td>headless host on local IPC; refuses when a host is running</td></tr><tr><td><code>tiktools rpc &lt;method&gt; [params-json] &amp;#124; rpc --stdio [--events]</code></td><td>untyped passthrough to any host method</td></tr><tr><td><code>tiktools rpc --stdio [--events]</code></td><td>NDJSON request/response loop on stdio</td></tr></tbody></table><h3 id="tiktools-web-—-local-browser-adapter-requires-the-local-web-feature" tabindex="-1"><code>tiktools web</code> — local browser adapter (requires the local-web feature) <a class="header-anchor" href="#tiktools-web-—-local-browser-adapter-requires-the-local-web-feature" aria-label="Permalink to “tiktools web — local browser adapter (requires the local-web feature)”">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools web --assets &lt;directory&gt; [--port N] [--join-origin URL] [--multi-session]</code></td><td>serve the local browser adapter; host --ipc must be running</td></tr><tr><td><code>tiktools web --print-code [--port N]</code></td><td>print the active pairing code without restarting</td></tr><tr><td><code>tiktools web --reset-session [--port N]</code></td><td>revoke every paired browser and print a fresh code <strong>destructive</strong></td></tr></tbody></table><h3 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to “Conventions”">​</a></h3><ul><li><strong>host resolution</strong>: commands run against the running host over local IPC; when no host is running they fail with host_unavailable instead of starting a second runtime. Use <code>tiktools --json system info</code> as the lightweight probe: exit 0 means a host answered, exit 3 means the IPC host is unavailable. --standalone runs the command against an isolated in-process runtime instead.</li><li><strong>output</strong>: stdout carries the result; diagnostics go to stderr. --json prints the raw result object; without it, lists print one line per item. json values may use @path to read from a file. Human help follows the display locale: TIKTOOLS_LANG overrides the LC_ALL/LC_MESSAGES/LANG chain, and machine output stays locale-independent.</li><li><strong>exit codes</strong>: 0 ok, 1 operation error, 2 usage error, 3 transport failure.</li><li><strong>secrets</strong>: live connect/pick read the session cookie from --session-cookie or the TIKTOOLS_SESSION_COOKIE environment variable (the flag wins); the value never appears in diagnostics. api call redacts secrets from its output unless --secrets-visible is passed, and refuses destructive methods without --confirm.</li></ul><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Operational details”">​</a></h2><p>The snapshot regenerates from a binary built with <code>--features local-web</code> so feature-gated domains (cloud, publisher, web) are complete. The provenance check in <code>docs check</code> compares hashes of every Rust source, so any command-spec change fails the build until the contract is regenerated. Normal docs builds never run Cargo.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/regenerate-control.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/generate-references.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/cli-coverage.ts</span></span></code></pre></div><p>Run the regeneration after changing any command parser or spec, then review the fragment diff as part of the change. Agents consuming <code>help --json</code> should treat schema version 1 as additive-stable: new verbs, domains or fields may appear without notice, existing keys keep their meaning.</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};